import { CanvasRecorder, downloadBlob } from 'wgpu-kit/media';
const recorder = new CanvasRecorder();
const canvas = document.querySelector<HTMLCanvasElement>('#canvas')!;
// Invoke start from a user action; keep rendering your canvas.
recorder.start(canvas, 8_000_000);
// Invoke this from a later Stop action.
async function finishRecording() {
  const result = await recorder.stop();
  const extension = result.mimeType.startsWith('video/mp4') ? 'mp4' : 'webm';
  downloadBlob(result.blob, `capture.${extension}`);
}
